 "content": "from collections import deque


def transform(grid):
    """Reverse the nested color layers of each nonzero rectangular object."""
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and not seen[ny][nx]:
                        seen[ny][nx] = True
                        q.append((ny, nx))

            r0 = min(y for y, _ in cells)
            r1 = max(y for y, _ in cells)
            c0 = min(x for _, x in cells)
            c1 = max(x for _, x in cells)
            mid_rows = sorted({(r0 + r1) // 2, (r0 + r1 + 1) // 2})
            mid_cols = sorted({(c0 + c1) // 2, (c0 + c1 + 1) // 2})
            paths = []
            # Rays from each side toward the object's center reveal outer-to-inner layers.
            for x in mid_cols:
                paths.extend([
                    [grid[y][x] for y in range(r0, (r0 + r1) // 2 + 1)],
                    [grid[y][x] for y in range(r1, (r0 + r1 + 1) // 2 - 1, -1)],
                ])
            for y in mid_rows:
                paths.extend([
                    [grid[y][x] for x in range(c0, (c0 + c1) // 2 + 1)],
                    [grid[y][x] for x in range(c1, (c0 + c1 + 1) // 2 - 1, -1)],
                ])

            sequences = []
            for path in paths:
                seq = []
                for color in path:
                    if not seq or color != seq[-1]:
                        seq.append(color)
                sequences.append(seq)
            order = max(sequences, key=lambda seq: (len(seq), len(set(seq))))
            # A selected center ray should visit each nested band once.
            colors = []
            for color in order:
                if color not in colors:
                    colors.append(color)
            mapping = dict(zip(colors, reversed(colors)))
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
    return out

